'use strict';
// An announced fictional calendar, independent of the random event generator.
const SEASON_BASE5={fresh,nextWeek,validateSave,menuSummary,productionNeeds,guestDemand5};
const SEASON_NAMES5=['Zima','Jaro','Léto','Podzim'];
const SEASON_EVENTS5={festival:{name:'Městský festival',groups:{office:1,specialty:1.12,community:1.08,tourist:1.22,student:1.08}},conference:{name:'Obchodní veletrh',groups:{office:1.2,specialty:1.04,community:1,tourist:1.1,student:1}},semester:{name:'Začátek semestru',groups:{office:1,specialty:1.03,community:1.02,tourist:1,student:1.2}},holidays:{name:'Konec roku · dovolené',groups:{office:.8,specialty:1,community:1.04,tourist:1.06,student:.75}}};
function ensureSeasons5(v){if(v.seasons5===undefined)v.seasons5={history:[]};return v;}
fresh=function(...args){return ensureSeasons5(SEASON_BASE5.fresh(...args))};ensureSeasons5(state);
function citySeason5(city,week=state.week){const index=CITIES.findIndex(c=>c.name===city);if(index<0||!Number.isInteger(week)||week<1||week>1000000)throw Error('Kalendář potřebuje platné město a týden.');
 const year=Math.floor((week-1)/52)+1,yearWeek=(week-1)%52+1,south=['Sydney','Melbourne'].includes(city),phase=(yearWeek-1+(south?26:0))%52+1,season=phase<10||phase>=49?0:phase<23?1:phase<36?2:3,tropical=city==='Singapur',hot=city==='Dubaj',mild=['Lisabon','Madrid','Sydney'].includes(city),base=tropical?28:hot?[21,29,37,29][season]:[3,14,24,12][season]+(mild?5:0),variation=(week*17+index*11)%7-3,temperature=base+variation,code=(week*13+index*7)%17,weather=temperature<=1&&code<7?'Sníh':code<4?'Déšť':temperature>=29?'Horko':code===7?'Vítr':'Klidné počasí',weatherFactor=weather==='Déšť'?.95:weather==='Sníh'?.93:weather==='Vítr'?.98:1;
 const events=[];if(yearWeek===(17+index*3-1)%48+1)events.push('festival');if(yearWeek===(35+index*5-1)%48+1)events.push('conference');if(yearWeek===10||yearWeek===37)events.push('semester');if(yearWeek===51||yearWeek===52)events.push('holidays');
 const seasonal={office:season===2?.92:1,student:season===2?.86:1,community:season===0?1.03:1,specialty:1,tourist:season===2?1.12:season===0?.94:1},factors={};for(const key of GUEST_KEYS5)factors[key]=Math.round(clamp(seasonal[key]*weatherFactor*events.reduce((n,e)=>n*SEASON_EVENTS5[e].groups[key],1),.65,1.35)*1000)/1000;
 return {city,week,year,yearWeek,season:SEASON_NAMES5[season],temperature,weather,events,factors};
}
function seasonDemandFactor5(s,week=state.week){const l=loc(s.id),o=citySeason5(l.city,week),mix=GUEST_MIX5[l.segment];return mix.reduce((n,w,i)=>n+w*o.factors[GUEST_KEYS5[i]],0);}
function seasonGlobalEvent5(){return null;}
menuSummary=function(s){const m=SEASON_BASE5.menuSummary(s),temperature=citySeason5(loc(s.id).city).temperature,warm=(state.week-1)%52>=20&&(state.week-1)%52<=36,drinks=m.drinks.map(d=>({...d,weight:d.weight*(d.id==='coldbrew'?(temperature>=23?2.2:temperature<=7?.45:1.1)/(warm?2:.6):d.id==='seasonal'?(temperature<=7?1.35:temperature>=23?.9:1):1)})),total=drinks.reduce((n,d)=>n+d.weight,0),average=key=>total?drinks.reduce((n,d)=>n+d[key]*d.weight,0)/total:0,foodMinutes=m.food.reduce((n,d)=>n+d.rate*d.minutes,0);return {...m,drinks,total,price:average('price'),cost:average('cost'),dose:average('dose'),minutes:average('minutes')+foodMinutes};};
productionNeeds=function(city){const needs=SEASON_BASE5.productionNeeds(city);for(const s of state.stores){if(city&&loc(s.id).city!==city&&!(city==='Praha'&&state.deliveryPolicy==='express'&&!state.roasters.some(r=>r.zone===loc(s.id).city&&r.auto)))continue;const dose=menuSummary(s).dose||.018;needs[s.blend]=(needs[s.blend]||0)+loc(s.id).traffic*dose*1.22*(seasonDemandFactor5(s)-1);}return needs;};
guestDemand5=function(s,d){SEASON_BASE5.guestDemand5(s,d);const factors=citySeason5(loc(s.id).city).factors,groups=d.guests5.groups,old=groups.reduce((n,g)=>n+g.weight,0);for(const g of groups)g.weight*=factors[g.id];const sum=groups.reduce((n,g)=>n+g.weight,0);for(const g of groups)g.weight*=old/Math.max(.00001,sum);return d;};
function seasonCalendar5(city,weeks=13){if(![4,13].includes(weeks))throw Error('Kalendář nabízí 4 nebo 13 týdnů.');const stores=state.stores.filter(s=>loc(s.id).city===city);return Array.from({length:weeks},(_,i)=>{const week=state.week+i,o=citySeason5(city,week),coffee=stores.reduce((n,s)=>{const previous=state.week;try{state.week=week;return n+loc(s.id).traffic*(menuSummary(s).dose||.018)*1.22*seasonDemandFactor5(s,week);}finally{state.week=previous}},0);return {...o,coffee,stores:stores.length};});}
function seasonForecast5(city,weeks=4){if(![4,13].includes(weeks)||!CITIES.some(c=>c.name===city))throw Error('Neplatný výhled kalendáře.');if(!state.stores.length)throw Error('Pro provozní výhled nejprve otevři kavárnu.');const original=state,series=[];try{state=JSON.parse(JSON.stringify(original));for(let i=0;i<weeks&&!state.over;i++){const h=nextWeek(),record=state.seasons5.history.at(-1),stores=record.stores.filter(s=>s.city===city);series.push({week:h.week,profit:h.profit,cash:h.cash,arrivals:stores.reduce((n,s)=>n+s.arrivals,0),served:stores.reduce((n,s)=>n+s.served,0),lost:stores.reduce((n,s)=>n+s.lost,0),used:stores.reduce((n,s)=>n+s.used,0),weather:record.cities.find(o=>o.city===city).weather});}return {week:original.week,city,weeks,series,over:state.over};}finally{state=original;}}
nextWeek=function(){const cities=CITIES.map(c=>citySeason5(c.name)),h=SEASON_BASE5.nextWeek(),stores=state.stores.filter(s=>s.last).map(s=>({id:s.id,city:loc(s.id).city,segment:loc(s.id).segment,factor:seasonDemandFactor5(s,h.week),arrivals:s.last.served+s.last.lost,served:s.last.served,lost:s.last.lost,used:s.last.used,profit:s.last.profit}));ensureSeasons5(state);state.seasons5.history.push({week:h.week,cities,stores});state.seasons5.history=state.seasons5.history.slice(-26);h.event='Místní sezóny a městský kalendář';return h;};
validateSave=function(input){const v=SEASON_BASE5.validateSave(input);ensureSeasons5(v);const fail=()=>{throw Error('Soubor obsahuje neplatnou historii kalendáře.');},n=(x,min=0,max=1e12)=>Number.isFinite(x)&&x>=min&&x<=max;if(!v.seasons5||!Array.isArray(v.seasons5.history)||v.seasons5.history.length>26)fail();let previous=0;
 for(const h of v.seasons5.history){if(!h||!Number.isInteger(h.week)||h.week<=previous||h.week>=v.week||!Array.isArray(h.cities)||h.cities.length!==CITIES.length||new Set(h.cities.map(o=>o.city)).size!==CITIES.length||!Array.isArray(h.stores)||h.stores.length>111||new Set(h.stores.map(s=>s.id)).size!==h.stores.length)fail();previous=h.week;for(const o of h.cities){if(!o||!CITIES.some(c=>c.name===o.city))fail();const expected=citySeason5(o.city,h.week);if(!['week','year','yearWeek','season','temperature','weather'].every(k=>o[k]===expected[k])||!Array.isArray(o.events)||o.events.length!==expected.events.length||!o.events.every((e,i)=>e===expected.events[i])||!o.factors||Object.keys(o.factors).length!==5||!GUEST_KEYS5.every(k=>o.factors[k]===expected.factors[k]))fail();}
 for(const s of h.stores){const l=loc(s.id);if(!l||s.city!==l.city||s.segment!==l.segment||!n(s.factor,.65,1.35)||Math.abs(s.factor-seasonDemandFactor5({id:s.id},h.week))>.000001||!['arrivals','served','lost','used'].every(k=>n(s[k]))||!n(s.profit,-1e12)||!Number.isInteger(s.arrivals)||!Number.isInteger(s.served)||!Number.isInteger(s.lost)||s.arrivals!==s.served+s.lost)fail();}}
 return v;};
